SELECT a.id, a.task_id, t.title AS task_title, t.publisher_id, t.reward_amount, a.acceptor_id, a.status, a.submit_content, a.submit_images AS submit_images_json, a.accepted_at, a.submitted_at, a.completed_at, t.deadline, a.reject_reason FROM task_acceptance a INNER JOIN task t ON a.task_id = t.id WHERE a.deleted = 0 AND a.acceptor_id = #{userId}
AND a.status = #{query.status}
ORDER BY a.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM task_acceptance a
WHERE a.deleted = 0 AND a.acceptor_id = #{userId}

    AND a.status = #{query.status}

